// Convert input polygons to CGAL polygons
    using Polygon_2 = std::vector<std::pair<double, double>>;
    using Polygon_with_holes_2 = std::pair<Polygon_2, std::vector<Polygon_2>>;

    auto to_cgal_polygon = [](const Polygon2d& poly) {
        Polygon_2 cgal_poly;
        for (const auto& point : poly) {
            cgal_poly.emplace_back(point.x(), point.y());
        }
        return cgal_poly;
    };

    Polygon_2 cgal_p1 = to_cgal_polygon(P1);
    Polygon_2 cgal_p2 = to_cgal_polygon(P2);

    // Perform union operation
    std::vector<Polygon_with_holes_2> result;
    if (!CGAL::join(cgal_p1, cgal_p2, std::back_inserter(result))) {
        // If union fails, return both polygons as separate results
        result.emplace_back(cgal_p1, std::vector<Polygon_2>());
        result.emplace_back(cgal_p2, std::vector<Polygon_2>());
    }

    // Convert CGAL result back to our format
    std::vector<PolygonWithHoles2d> output;
    for (const auto& poly_with_holes : result) {
        Polygon2d outer;
        for (const auto& point : poly_with_holes.first) {
            outer.emplace_back(point.first, point.second);
        }

        std::vector<Polygon2d> holes;
        for (const auto& hole : poly_with_holes.second) {
            Polygon2d hole_poly;
            for (const auto& point : hole) {
                hole_poly.emplace_back(point.first, point.second);
            }
            holes.push_back(hole_poly);
        }

        output.emplace_back(outer, holes);
    }

    return output;
    // END_CODE

